    "page.connType.shadow.h2.find-shadow-matches": "Thola Imidlalo Emnyama",
    "page.connType.shadow.p.calculate-your-four-totem-animals-then": "Bala izilwane zakho ezine zama-totem, bese ubheka kumbhalo wokubhalisa okuzithandela wabantu ababelana ngalolu hlobo lokuxhumana nawe.",
    "page.connType.shadow.btn.totem-connections-directory": "Totem Connections Directory",
