    "page.connType.mirror-opposite.section-label.connection-type": "Uhlobo Lokuxhumana",
    "page.connType.mirror-opposite.h1.mirror-opposite": "Isibuko Esiphambene",
    "page.connType.mirror-opposite.p.opposites-on-the-zodiac-wheel-six": "Okuphambene kumbuthano we-zodiac — izimpawu eziyisithupha kude, zibheke ngqo komunye nomunye emjikelezweni. Kufanele kahle ukubheka izindawo ezingabonakali nokufunda ngombono ohlukile ngokuphelele.",
    "page.connType.mirror-opposite.p.totem-connections": "<a href=\"connections.html?v=20260807\">← Totem Connections</a>",
    "page.connType.mirror-opposite.p.opposites-on-the-zodiac-wheel-six.2": "Okuphambene emjikelezweni we-zodiac — izimpawu eziyisithupha zihlukaniswe, zibhekene ngomunye ngokuthe ngqo phezu kwesiyingi. Lezi zinhlangano zilungele ngokuphelele ukuzibheka kanye nokubona izindawo ezimnyama komunye nomunye — njengoba zibhekene ngqo ngendlela ephambene neyona oyibhekileyo! Lokhu kungadala izingxabano ezishisayo, kodwa inqobo nje uma uletha inhlonipho eyanele, kunezinto eziningi ongazifunda lapha ezibonakalayo — nobabili ningabona izinto okungenzeka ukuthi omunye akakwazi ukuzibona, ngakho inqobo nje uma ninethemba komunye nomunye futhi nenza izinto ngenhloso enhle, lokhu kungaba ukuhlanganiswa okusiza kakhulu futhi okuhle kakhulu. Ngenxa yalokho, kuzohlala kuheha, njengoba nakaningi bezoba nombono ohlukile ezintweni kunalowenu, kwesinye isikhathi kuhluke kakhulu kangangokuba awuzange ucabange ukuthi kungenzeka!",
    "page.connType.mirror-opposite.h3.other-connection-types": "Ezinye izinhlobo zokuxhumana",
    "page.connType.mirror-opposite.li.rainbow": "<a href=\"connection-rainbow.html?v=20260807\">Iribhoni</a>",
