    "page.connType.mirror-opposite.h2.find-mirror-opposite-matches": "Thola Ukufanisa Okuhambisana Nesibuko",
    "page.connType.mirror-opposite.p.calculate-your-four-totem-animals-then": "Bala izilwane zakho ezine zama-totem, bese ubheka kusizindalwazi sokuzikhethela yabantu ababelana ngalolu hlobo lokuxhumana nawe.",
    "page.connType.mirror-opposite.btn.totem-connections-directory": "Totem Connections Directory",
    "page.connType.mirror-opposite.btn.totem-animals-calculator": "Totem Animals Calculator",
    "page.connType.values-trine.section-label.connection-type": "Uhlobo Lokuxhumana",
    "page.connType.values-trine.h1.values-trine": "Amanani Trine",
    "page.connType.values-trine.p.shared-value-both-animals-belong-to": "Inani elabelwe — kokubili izilwane zingaphansi kwe-Triangle Yezinani elifanayo, ngakho-ke kuvamile ukukhuluma ulimi olulodwa uma kukhulunywa ngezinto ezibalulekile ekuphileni.",
    "page.connType.values-trine.p.totem-connections": "<a href=\"connections.html?v=20260807\">← Totem Connections</a>",
    "page.connType.values-trine.p.shared-value-both-animals-belong-to.2": "Inani elabelanayo — kokubili izilwane zingaphansi kwe-Triangle Yamanani elifanayo: Amandla & Isidumo, Ukuphepha & Uzimele, Ugqozi & Ukuziphatha Okuphezulu, noma Ukuthula & Ukubambisana. Lezi zinxanxathela yizinto zabantu abakhuluma ulimi olufanayo nawe, ngokwezinto ezibaluleke kuwe. Banokufana ezicabangweni zabo mayelana nokuphatha ukuphila — noma ngabe lokho kuwukufuna amandla nobuciko emsebenzini, noma ukufuna ukuthula nendlela yokuphila elula. Laba ngabantu ongadingi ukubachazela kakhulu, ngoba sebesevele bekulesi simo nawe, ngakho kungaba kuhle kunoma yiluphi uhlobo lobudlelwane: ibhizinisi noma injabulo, umndeni noma ubungane. Ukugijima okuhle :)",
    "page.connType.values-trine.h3.other-connection-types": "Ezinye izinhlobo zokuxhumana",
    "page.connType.values-trine.li.rainbow": "<a href=\"connection-rainbow.html?v=20260807\">Iribhoni</a>",
    "page.connType.values-trine.li.shadow": "<a href=\"connection-shadow.html?v=20260807\">Umthunzi</a>",
